#include <array>
#include <cassert>
#include <cstdlib>
#include <iostream>
using namespace std;
using Mat=array<array<int,3>,3>;
int p;
int m(int a){a%=p;return a<0?a+p:a;}
int rank3(Mat A){int r=0;for(int c=0;c<3;c++){int k=r;while(k<3&&!A[k][c])k++;if(k==3)continue;swap(A[k],A[r]);int inv=1;while(m(inv*A[r][c])!=1)inv++;for(int j=c;j<3;j++)A[r][j]=m(A[r][j]*inv);for(int i=0;i<3;i++)if(i!=r){int v=A[i][c];for(int j=c;j<3;j++)A[i][j]=m(A[i][j]-v*A[r][j]);}r++;}return r;}
array<int,3> app(const array<int,3>&x,const array<int,3>&y,const array<array<int,2>,2>&T){array<int,3>z={0,0,0};for(int i=0;i<2;i++){z[i+1]=m(x[0]*(T[i][0]*y[1]+T[i][1]*y[2]));}return z;}
array<int,3> mul(Mat N,const array<int,3>&x){array<int,3>z={0,0,0};for(int i=0;i<3;i++)for(int j=0;j<3;j++)z[i]=m(z[i]+N[i][j]*x[j]);return z;}
bool direct(Mat N, const array<array<int,2>,2>&T){for(int i=0;i<3;i++)for(int j=0;j<3;j++){array<int,3>x={0,0,0},y={0,0,0};x[i]=y[j]=1;auto Nx=mul(N,x),Ny=mul(N,y);auto a=app(Nx,Ny,T),b=app(Nx,y,T),c=app(x,Ny,T),d=app(x,y,T);for(int k=0;k<3;k++)b[k]=m(b[k]+c[k]-mul(N,d)[k]);auto e=mul(N,b);if(a!=e)return false;}return true;}
bool criterion(Mat N,const array<array<int,2>,2>&T){if(N[0][1]||N[0][2])return false;int a=N[0][0],B[2][2],C[2][2];for(int i=0;i<2;i++)for(int j=0;j<2;j++)B[i][j]=m(N[i+1][j+1]-(i==j?a:0));for(int i=0;i<2;i++)for(int j=0;j<2;j++){C[i][j]=0;for(int k=0;k<2;k++)C[i][j]=m(C[i][j]+T[i][k]*B[k][j]-B[i][k]*T[k][j]);}for(int i=0;i<2;i++){int val=0;for(int j=0;j<2;j++)for(int k=0;k<2;k++)val=m(val+B[i][j]*T[j][k]*N[k+1][0]);if(val)return false;for(int k=0;k<2;k++){val=0;for(int j=0;j<2;j++)val=m(val+B[i][j]*C[j][k]);if(val)return false;}}return true;}
bool prediction(Mat N,const array<array<int,2>,2>&T,bool irr){if(N[0][1]||N[0][2])return false;int a=N[0][0];int b00=m(N[1][1]-a),b01=N[1][2],b10=N[2][1],b11=m(N[2][2]-a);bool zero=!b00&&!b01&&!b10&&!b11;bool u0=!N[1][0]&&!N[2][0];if(irr){bool commute=true;int Bv[2][2]={{b00,b01},{b10,b11}};for(int i=0;i<2;i++)for(int j=0;j<2;j++){int s=0;for(int k=0;k<2;k++)s+=T[i][k]*Bv[k][j]-Bv[i][k]*T[k][j];if(m(s)!=0)commute=false;};return zero||(u0&&commute);} else {bool lower=(b01==0&&b11==0&&N[1][0]==0);bool upper=(b10==0&&b00==0&&N[2][0]==0);bool diag=(b01==0&&b10==0&&u0);return zero||lower||upper||diag;}}
int main(){for(int q: {2,3,5}){p=q;for(int type=0;type<2;type++){if(type==1&&p==2)continue;array<array<int,2>,2>T={{{0,p==2?1:2},{1,p==2?1:0}}};if(type==1)T={{{1,0},{0,2}}};long long cnt[4]={0,0,0,0};long long cases=1;for(int i=0;i<9;i++)cases*=p;for(long long mask=0;mask<cases;mask++){Mat N{};long long tmp=mask;for(int j=0;j<3;j++)for(int i=0;i<3;i++){N[i][j]=tmp%p;tmp/=p;}bool truth=direct(N,T),crit=criterion(N,T),pred=prediction(N,T,type==0);if(truth!=crit||truth!=pred){cerr<<"FAILED p "<<p<<" type "<<type<<" mask "<<mask<<" direct "<<truth<<" crit "<<crit<<" pred "<<pred<<"\n";return 1;}if(truth)cnt[rank3(N)]++;}long long Q=p,total=cnt[0]+cnt[1]+cnt[2]+cnt[3];long long expected=type==0?2*Q*Q*Q-Q:Q*(2*Q*Q*Q+2*Q*Q-4*Q+1);if(total!=expected){cerr<<"COUNT FAILED p="<<p<<" type="<<type<<" actual="<<total<<" expected="<<expected<<"\n";return 2;}if(type==0){long long ex[4]={1,Q*Q+Q-2,Q*Q-1,2*(Q-1)*(Q*Q-1)};for(int i=0;i<4;i++)if(cnt[i]!=ex[i]){cerr<<"RANK FAILED "<<i<<"\n";return 3;}}cout<<"PASS q="<<p<<" quadratic="<<(type==0?"irreducible":"split_distinct")<<" checked="<<cases<<" ranks="<<cnt[0]<<","<<cnt[1]<<","<<cnt[2]<<","<<cnt[3]<<" total="<<total<<"\n";}}cout<<"QUADRATIC_PRELIE_NIJENHUIS_VERIFIED\n";}
